<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
define('RUBIZH_AUTH',true);require dirname(__DIR__).'/api/lib.php';require dirname(__DIR__).'/shop/store-lib.php';
/** Keep historical statuses and contract versions intact. Populate only proven empty presentation fields. */
function crmStatePlan(PDO $db): array {
 $rows=[];$counts=['total_legacy_records'=>0,'safe_mappings'=>0,'ambiguous_mappings'=>0,'conflicts'=>0,'already_mapped'=>0];$last=0;
 do{$q=$db->prepare('SELECT * FROM rubizh_customer_orders WHERE id>? AND (pim_contract_version IS NULL OR pim_contract_version<>3) ORDER BY id LIMIT 250');$q->execute([$last]);$batch=$q->fetchAll(PDO::FETCH_ASSOC);foreach($batch as $o){$id=$last=(int)$o['id'];$counts['total_legacy_records']++;$ships=npShipments($db,$id);$left=npRemaining(npLines($db,$id),$ships);$o['shipment_coverage_complete']=(bool)$left&&!array_filter($left,fn($l)=>abs($l['qty'])>0.00001);$invoices=crmQuery($db,'SELECT * FROM rubizh_mono_invoices WHERE order_id=? ORDER BY id',[$id]);$dto=shopCanonicalOrder($o,$ships,$invoices);$type=in_array('STATE_CONFLICT',$dto['review_flags'],true)?'conflicts':($dto['review_required']?'ambiguous_mappings':'safe_mappings');foreach(['order_status'=>'pim_order_state','payment_status'=>'pim_payment_state','fulfillment_status'=>'pim_fulfillment_state'] as $k=>$c)if(($o[$c]??null)!==null&&$o[$c]!==$dto[$k])$type='conflicts';if($type==='safe_mappings'&&$o['pim_order_state']!==null&&$o['pim_payment_state']!==null&&$o['pim_fulfillment_state']!==null)$type='already_mapped';$counts[$type]++;$rows[]=['id'=>$id,'classification'=>$type,'canonical'=>$dto,'snapshot_hash'=>hash('sha256',json_encode([$o,$ships,$invoices],JSON_THROW_ON_ERROR))];}}while(count($batch)===250);
 return ['mode'=>'PLAN','writes'=>0,'counts'=>$counts,'records'=>$rows];
}
try{$o=getopt('',['plan','apply','config:','database:','isolated','plan-sha256:','backup-file:','backup-sha256:']);if(isset($o['plan'])===isset($o['apply']))throw new RuntimeException('Choose plan/apply');if(isset($o['config'])){$GLOBALS['rubizh_config_override']=null;throw new RuntimeException('Use private api/config.php of the selected checkout');}$db=rubizhDatabaseConnect(cfg());pimV3DetectColumns($db);$name=(string)$db->query('SELECT DATABASE()')->fetchColumn();$db->exec('SET TRANSACTION READ ONLY');$db->beginTransaction();$plan=crmStatePlan($db);$db->rollBack();$hash=hash('sha256',json_encode($plan,JSON_THROW_ON_ERROR));
 if(isset($o['plan'])){echo json_encode($plan+['plan_sha256'=>$hash],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)."\n";exit;}
 if(($o['database']??'')!==$name||!hash_equals($hash,(string)($o['plan-sha256']??'')))throw new RuntimeException('Database or plan changed');$backup=realpath((string)($o['backup-file']??''));if(!$backup||str_starts_with($backup,dirname(__DIR__).'/')||filesize($backup)<1024||!hash_equals(hash_file('sha256',$backup),(string)($o['backup-sha256']??'')))throw new RuntimeException('Verified off-webroot backup required');if(isset($o['isolated'])&&(!preg_match('/^fixture_[a-z0-9_]+$/D',$name)||!getenv('RUBIZH_TEST_MYSQL_SOCKET')||cfg('db_host')!=='localhost'))throw new RuntimeException('Fixture only');if(!crmSchemaReady($db))throw new RuntimeException('CRM schema required');$applied=[];
 // Hold all relevant order locks before checking the exact approved plan again.
 $locks=[];try{foreach($plan['records'] as $r){$key='rubizh_np_order_'.$r['id'];$q=$db->prepare('SELECT GET_LOCK(?,10)');$q->execute([$key]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Order busy');$locks[]=$key;}$db->beginTransaction();try{$current=crmStatePlan($db);if(!hash_equals($hash,hash('sha256',json_encode($current,JSON_THROW_ON_ERROR))))throw new RuntimeException('Plan stale');foreach($plan['records'] as $r)if($r['classification']==='safe_mappings'){$id=$r['id'];$before=crmOne($db,'SELECT pim_order_state,pim_payment_state,pim_fulfillment_state FROM rubizh_customer_orders WHERE id=? FOR UPDATE',[$id]);$v=$r['canonical'];$db->prepare('UPDATE rubizh_customer_orders SET pim_order_state=COALESCE(pim_order_state,?),pim_payment_state=COALESCE(pim_payment_state,?),pim_fulfillment_state=COALESCE(pim_fulfillment_state,?) WHERE id=?')->execute([$v['order_status'],$v['payment_status'],$v['fulfillment_status'],$id]);crmAudit($db,null,'order',(string)$id,'legacy.canonical_backfill',$before,['order_status'=>$v['order_status'],'payment_status'=>$v['payment_status'],'fulfillment_status'=>$v['fulfillment_status']],'Безпечне відображення зі схваленого плану',null,'MIGRATION');$applied[]=$id;}$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}finally{foreach($locks as $key){$q=$db->prepare('SELECT RELEASE_LOCK(?)');$q->execute([$key]);}}
 echo json_encode(['mode'=>'APPLY','applied_safe_records'=>$applied,'historical_status_changes'=>0,'contract_version_changes'=>0],JSON_THROW_ON_ERROR)."\n";
}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();fwrite(STDERR,"Canonical backfill refused: ".$e->getMessage()."\n");exit(1);}
